.pagination li a {
  display: block;
  padding: 8px 12px;
  text-decoration: none;
  border: 1px solid gray;
  color: black;
  margin: 0 4px;
  border-radius: 5px;
  transition: background-color 1s;
}

ul.breadcrumb {
  padding: 8px;
  list-style: none;
  background-color: #eee;
}
ul.breadcrumb li {
  display: inline;
}
ul.breadcrumb li a {
  color: green;
}
ul.breadcrumb li+li:before {
  padding: 8px;
  color: black;
  content: "/\00a0";
}
